-- 1. Hide the fence rows. Text is untouched.
vim.api.nvim_buf_set_extmark(buf, ns, plan.first, 0, {
	end_row = plan.last,
	end_col = #last_line,
	conceal_lines = "",
})

-- 2. Draw the diagram as virtual rows on the anchor row.
vim.api.nvim_buf_set_extmark(buf, ns, plan.anchor, 0, {
	virt_lines = plan.lines, -- { { {text, hl_group}, ... }, ... }
	virt_lines_above = plan.above,
	virt_lines_overflow = "scroll",
})
